function findAnagrams(s, p) {
  const result = [];
  const sorted = (x) => [...x].sort().join("");
  const target = sorted(p);
  for (let i = 0; i + p.length <= s.length; i++) {
    if (sorted(s.slice(i, i + p.length)) === target) result.push(i);   // re-sort every window
  }
  return result;
}

List<Integer> findAnagrams(String s, String p) {
    List<Integer> result = new ArrayList<>();
    char[] target = p.toCharArray();
    Arrays.sort(target);
    for (int i = 0; i + p.length() <= s.length(); i++) {
        char[] window = s.substring(i, i + p.length()).toCharArray();
        Arrays.sort(window);                     // re-sort every window
        if (Arrays.equals(window, target)) result.add(i);
    }
    return result;
}

vector<int> findAnagrams(string s, string p) {
    vector<int> result;
    string target = p;
    sort(target.begin(), target.end());
    for (size_t i = 0; i + p.size() <= s.size(); i++) {
        string window = s.substr(i, p.size());
        sort(window.begin(), window.end());      // re-sort every window
        if (window == target) result.push_back(i);
    }
    return result;
}

function findAnagrams(s, p) {
  const result = [];
  if (p.length > s.length) return result;
  const need = new Array(26).fill(0), have = new Array(26).fill(0);
  for (const ch of p) need[ch.charCodeAt(0) - 97]++;
  const same = () => need.every((c, k) => c === have[k]);   // 26 comparisons: O(1)
  for (let right = 0; right < s.length; right++) {
    have[s.charCodeAt(right) - 97]++;                // the window takes in s[right]...
    const left = right - p.length + 1;
    if (left < 0) continue;                          // not full yet
    if (same()) result.push(left);                   // ...counts match: an anagram starts at left
    have[s.charCodeAt(left) - 97]--;                 // ...then lets go of s[left]
  }
  return result;
}

List<Integer> findAnagrams(String s, String p) {
    List<Integer> result = new ArrayList<>();
    if (p.length() > s.length()) return result;
    int[] need = new int[26], have = new int[26];
    for (char ch : p.toCharArray()) need[ch - 'a']++;
    for (int right = 0; right < s.length(); right++) {
        have[s.charAt(right) - 'a']++;           // the window takes in s[right]...
        int left = right - p.length() + 1;
        if (left < 0) continue;                  // not full yet
        if (Arrays.equals(have, need)) result.add(left);   // ...counts match: an anagram at left
        have[s.charAt(left) - 'a']--;            // ...then lets go of s[left]
    }
    return result;
}

vector<int> findAnagrams(string s, string p) {
    vector<int> result;
    if (p.size() > s.size()) return result;
    vector<int> need(26, 0), have(26, 0);
    for (char ch : p) need[ch - 'a']++;
    for (int right = 0; right < (int)s.size(); right++) {
        have[s[right] - 'a']++;                  // the window takes in s[right]...
        int left = right - (int)p.size() + 1;
        if (left < 0) continue;                  // not full yet
        if (have == need) result.push_back(left);   // ...counts match: an anagram starts at left
        have[s[left] - 'a']--;                   // ...then lets go of s[left]
    }
    return result;
}
